<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Neuron Network Simulation</title>
  <script src="https://cdnjs.cloudflare.com/ajax/libs/dat-gui/0.7.9/dat.gui.min.js"></script>
  <style>
    body {
      margin: 0;
      padding: 0;
      background-color: #05070f;
      display: flex;
      justify-content: center;
      align-items: center;
      min-height: 100vh;
